package io.github.aristheg201.svarcade.native.game
import kotlin.test.*
class NativeBotPlannerTest{
 @Test fun `uno bot plays a legal visible card before draw`(){val v=NativeGameView("u","uno","UNO","playing",turn="Bot",cards=listOf(NativeCardView("0","RED 5","Có thể đánh","red",5,mapOf("kind" to "number","color" to "red")),NativeCardView("1","BLUE 7","","blue",7,mapOf("kind" to "number","color" to "blue"))),fields=mapOf("activeColor" to "red"));val p=NativeBotPlanner.plan(v,NativeBotDifficulty.HARD);assertEquals("play",p.candidates.first().action);assertEquals("0",p.candidates.first().args["index"])}
 @Test fun `tft bot eventually includes ready`(){val v=NativeGameView("t","tft","TFT","shop",boardWidth=7,boardHeight=4,board=List(28){""},cards=listOf(NativeCardView("shop:0","pikachu","Cost 1g","shop",1)),actions=listOf(NativeActionView("ready","Ready",enabled=true)),fields=mapOf("gold" to "10","bench" to ""));assertTrue(NativeBotPlanner.plan(v,NativeBotDifficulty.NORMAL).candidates.any{it.action=="ready"})}
 @Test fun `tower defense bot can start an idle wave`(){val b=MutableList(96){""}.also{it[12]="path:start";it[13]="path"};val v=NativeGameView("td","tower_defense","TD","prepare",boardWidth=12,boardHeight=8,board=b,cards=listOf(NativeCardView("pikachu","Pikachu","35g","electric",35)),fields=mapOf("gold" to "120","running" to "false"));val a=NativeBotPlanner.plan(v,NativeBotDifficulty.HARD).candidates;assertTrue(a.any{it.action=="start_wave"});assertTrue(a.any{it.action=="deploy"})}
 @Test fun `tft positioning derives from configured geometry`(){val slots=TftBotPlanner.formationSlots("ranger",NativeBotDifficulty.HARD,9,6);assertTrue(slots.all{it in 0 until 54});assertTrue(slots.take(9).all{it/9==5});assertFalse(slots.contains(24) && slots.size<28)}
}
